<?php
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
try{require_once __DIR__.'/../Config/database.php';require_once __DIR__.'/../Config/mikrotik.php';$pdo=(new Database())->connect();$cfg=new MikroTikConfig();$router=$cfg->getRouter();$rid=(int)($router['id']??0);$where="created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND (LOWER(alarm_type) LIKE 'pppoe%' OR LOWER(interface_name) LIKE '%pppoe%')";$params=[];if($rid>0){$where.=' AND router_id=?';$params[]=$rid;}$st=$pdo->prepare("SELECT alarm_type,severity,status,interface_name,message,value,threshold,created_at,resolved_at FROM alarms WHERE {$where} ORDER BY created_at DESC");$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$u=[];foreach($rows as $r){$i=trim((string)$r['interface_name']," <>\t\n\r\0\x0B");$n=null;if(preg_match('/^pppoe-(.+)$/i',$i,$m))$n=$m[1];elseif(preg_match('/^PPPoE\s+(.+?)\s+(?:download|upload)\s+/i',(string)$r['message'],$m))$n=trim($m[1]);if(!$n)continue;if(!isset($u[$n]))$u[$n]=['username'=>$n,'alarms'=>0,'critical'=>0,'active'=>0,'download'=>0,'upload'=>0,'sum_ratio'=>0,'peak_ratio'=>0,'last'=>$r['created_at']];$x=&$u[$n];$x['alarms']++;$s=strtolower((string)$r['severity']);if($s==='critical')$x['critical']++;if(strtolower((string)$r['status'])==='active')$x['active']++;$t=strtolower((string)$r['alarm_type']);if(strpos($t,'download')!==false)$x['download']++;if(strpos($t,'upload')!==false)$x['upload']++;$v=(float)$r['value'];$th=(float)$r['threshold'];$ratio=$th>0?$v/$th:0;$x['sum_ratio']+=$ratio;$x['peak_ratio']=max($x['peak_ratio'],$ratio);unset($x);}foreach($u as &$x){$avg=$x['alarms']?$x['sum_ratio']/$x['alarms']:0;$risk=min(100,round($x['alarms']*4+$x['critical']*9+$x['active']*12+$avg*25+$x['peak_ratio']*10));$x['risk_score']=$risk;$x['risk']=$risk>=70?'HIGH':($risk>=40?'MEDIUM':'LOW');$reasons=[];if($x['critical'])$reasons[]=$x['critical'].' critical';if($x['active'])$reasons[]=$x['active'].' active';if($avg>=.8)$reasons[]='usage tinggi';if($x['alarms']>=5)$reasons[]='alarm berulang';$x['reason']=$reasons?implode(', ',$reasons):'stabil';$x['avg_usage_percent']=round($avg*100,1);$x['peak_usage_percent']=round($x['peak_ratio']*100,1);unset($x['sum_ratio'],$x['peak_ratio']);}unset($x);usort($u,fn($a,$b)=>$b['risk_score']<=>$a['risk_score']);echo json_encode(['success'=>true,'period'=>'30d','router_id'=>$rid,'router_name'=>$router['router_name']??null,'users'=>array_values($u)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'message'=>'Risk ranking unavailable']);}
